package org.apache.commons.lang3.function.failable;

import org.apache.commons.lang3.function.failable.Failable;

public final class FailableHelper {

    public static <E extends Throwable> void run(final Object test, final FailableRunnable<E> runnable) {
        if (runnable != null && test != null) {
            try {
                runnable.run();
            } catch (final Throwable t) {
                throw Failable.rethrow(t);
            }
        }
    }

    private FailableHelper() {
        // empty
    }
}
